const INVESTORS_CLASSROOM: VideoDef[] = [
  {
    slug: "reading-a-bond-term-sheet",
    title: { en: "Masterclass: reading a bond term sheet", fr: "Masterclass : lire les conditions d'une émission obligataire" },
    summary: { en: "A 25-minute masterclass that walks through every line of a sovereign bond term sheet, from issuer to redemption schedule, and shows how each one changes risk and price.", fr: "Une masterclass de 25 minutes qui parcourt chaque ligne des conditions d'une émission obligataire souveraine, de l'émetteur au calendrier de remboursement, et montre comment chacune modifie le risque et le prix." },
    durationSeconds: 1500,
    topics: ["bonds", "cemac", "markets"],
    productionStage: "storyboard",
    accessTier: "member",
    relatedCourseSlug: "government-bonds-and-treasury-securities",
    relatedLabSlug: "bonds",
    script: {
      hook: { en: "Every bond tells you exactly what it will do. The skill is reading it before you buy, not after.", fr: "Chaque obligation vous dit exactement ce qu'elle fera. L'art, c'est de la lire avant d'acheter, pas après." },
      scenes: [
        { seconds: 240, title: { en: "Chapter 1 · The issuer and the visa", fr: "Chapitre 1 · L'émetteur et le visa" }, visual: { en: "Studio set with a large screen. A sample term sheet (fictional, clearly watermarked 'illustrative') scrolls; the presenter circles 'Issuer', 'Guarantor', 'COSUMAF visa number'.", fr: "Plateau avec grand écran. Un exemple de conditions d'émission (fictif, filigrané « illustratif ») défile ; le présentateur entoure « Émetteur », « Garant », « Numéro de visa COSUMAF »." }, narration: { en: "We start where every analyst starts: who is borrowing, who stands behind them, and whether the regulator has approved the public offer. A visa means the documentation met the rules. It does not mean the regulator vouches for repayment. Those are different things, and confusing them is the first mistake.", fr: "Nous commençons là où commence tout analyste : qui emprunte, qui le garantit, et si le régulateur a approuvé l'offre publique. Un visa signifie que la documentation respecte les règles. Il ne signifie pas que le régulateur se porte garant du remboursement. Ce sont deux choses différentes, et les confondre est la première erreur." } },
        { seconds: 240, title: { en: "Chapter 2 · Nominal, coupon, frequency", fr: "Chapitre 2 · Nominal, coupon, fréquence" }, visual: { en: "The screen isolates three fields: nominal value 10,000 FCFA, coupon 'x% per year' (illustrative), payment frequency. A calendar animates coupon dates.", fr: "L'écran isole trois champs : valeur nominale 10 000 FCFA, coupon « x % par an » (illustratif), fréquence de paiement. Un calendrier anime les dates de coupon." }, narration: { en: "Nominal value is what one bond represents, commonly 10,000 francs on this market. The coupon is the annual interest as a percentage of that nominal. Frequency tells you whether it arrives once or twice a year. Together they give you the cash you will actually receive, on which dates, before any price movement.", fr: "La valeur nominale est ce que représente une obligation, couramment 10 000 francs sur ce marché. Le coupon est l'intérêt annuel en pourcentage de ce nominal. La fréquence indique s'il arrive une ou deux fois par an. Ensemble, ils donnent les flux que vous recevrez réellement, à quelles dates, avant tout mouvement de prix." } },
        { seconds: 270, title: { en: "Chapter 3 · Maturity and amortisation", fr: "Chapitre 3 · Échéance et amortissement" }, visual: { en: "Two repayment profiles side by side: bullet (all principal at the end) versus amortising (principal returned in slices each year, often after a grace period). Cash-flow bars compare them.", fr: "Deux profils de remboursement côte à côte : in fine (tout le capital à la fin) contre amortissable (capital restitué par tranches chaque année, souvent après un différé). Des barres de flux les comparent." }, narration: { en: "Maturity is when the last franc comes back. But how it comes back matters just as much. Many CEMAC sovereign bonds amortise: after a grace period of a year or two, part of the principal is repaid every year alongside the coupon. That shortens your real exposure and changes the price sensitivity completely. Read the amortisation table, not just the maturity date.", fr: "L'échéance, c'est le moment où le dernier franc revient. Mais la manière dont il revient compte tout autant. Beaucoup d'obligations souveraines de la CEMAC sont amortissables : après un différé d'un ou deux ans, une partie du capital est remboursée chaque année avec le coupon. Cela raccourcit votre exposition réelle et change totalement la sensibilité du prix. Lisez le tableau d'amortissement, pas seulement la date d'échéance." } },
        { seconds: 270, title: { en: "Chapter 4 · Price, yield and duration", fr: "Chapitre 4 · Prix, rendement et duration" }, visual: { en: "Live demonstration on the Bond Explorer lab: the presenter moves the market-yield slider; price and duration readouts respond. A whiteboard shows the inverse relationship.", fr: "Démonstration en direct sur le laboratoire Explorateur d'obligations : le présentateur déplace le curseur de taux de marché ; le prix et la duration réagissent. Un tableau blanc montre la relation inverse." }, narration: { en: "Now the part most people skip. The coupon is fixed; the price is not. If market yields rise after issue, your bond's price falls so that a new buyer earns the market rate. Duration tells you how much: a bond with a duration of four loses roughly 4 percent for each percentage point rise in yield. Longer, bullet bonds have higher duration. Amortising ones have less. This is why two bonds with the same coupon can behave completely differently.", fr: "Maintenant, la partie que la plupart sautent. Le coupon est fixe ; le prix ne l'est pas. Si les taux de marché montent après l'émission, le prix de votre obligation baisse pour qu'un nouvel acheteur obtienne le taux du marché. La duration vous dit de combien : une obligation de duration quatre perd environ 4 % pour chaque point de hausse des taux. Les obligations longues in fine ont une duration élevée. Les amortissables, moins. C'est pourquoi deux obligations au même coupon peuvent se comporter de façon totalement différente." } },
        { seconds: 240, title: { en: "Chapter 5 · Listing, liquidity and the intermediary", fr: "Chapitre 5 · Cotation, liquidité et intermédiaire" }, visual: { en: "Fields highlighted: 'Listing: BVMAC', 'Paying agent', 'Placement syndicate'. A sparse order book appears beside.", fr: "Champs surlignés : « Cotation : BVMAC », « Agent payeur », « Syndicat de placement ». Un carnet d'ordres clairsemé apparaît à côté." }, narration: { en: "Where will this trade afterwards, and through whom? A BVMAC listing gives you a way out before maturity, but on a thin market that exit can be slow and priced below what the formula says. The paying agent is who actually sends your coupons. The placement syndicate are the brokers who sold it. If a seller can't name these, they aren't selling a listed bond.", fr: "Où ce titre se négociera-t-il ensuite, et par qui ? Une cotation à la BVMAC offre une sortie avant l'échéance, mais sur un marché étroit cette sortie peut être lente et à un prix inférieur à ce que dit la formule. L'agent payeur est celui qui verse réellement vos coupons. Le syndicat de placement regroupe les sociétés de bourse qui l'ont vendue. Si un vendeur ne peut pas les nommer, il ne vend pas une obligation cotée." } },
        { seconds: 240, title: { en: "Chapter 6 · Putting it together: a checklist", fr: "Chapitre 6 · Synthèse : une liste de contrôle" }, visual: { en: "A ten-line checklist builds on screen; the presenter ticks each with a sample sheet. Final frame: the checklist as a downloadable card.", fr: "Une liste de contrôle en dix lignes se construit à l'écran ; le présentateur coche chaque point sur un exemple. Image finale : la liste sous forme de fiche téléchargeable." }, narration: { en: "Let's close with the ten questions to answer before touching any bond: issuer, guarantor, visa, nominal, coupon, frequency, maturity, amortisation profile, listing venue, and who pays you. If you can answer all ten from the document, you understand what you're buying. If you can't, the document is the problem, not you.", fr: "Terminons par les dix questions à résoudre avant de toucher à une obligation : émetteur, garant, visa, nominal, coupon, fréquence, échéance, profil d'amortissement, lieu de cotation, et qui vous paie. Si vous pouvez répondre aux dix à partir du document, vous comprenez ce que vous achetez. Sinon, c'est le document qui pose problème, pas vous." } },
      ],
      closing: { en: "Download the checklist, open the Bond Explorer, and read a real term sheet from a recent CEMAC issue with it beside you.", fr: "Téléchargez la liste de contrôle, ouvrez l'Explorateur d'obligations, et lisez les conditions d'une émission récente de la CEMAC avec la liste à vos côtés." },
      disclaimer: { en: "The term sheet shown is illustrative and fictional. No actual issue, coupon or price is quoted. This masterclass is financial education, not a recommendation to buy any security.", fr: "Les conditions d'émission présentées sont illustratives et fictives. Aucune émission, coupon ou prix réel n'est cité. Cette masterclass relève de l'éducation financière et n'est pas une recommandation d'achat d'un titre." },
    },
  },
];

